// ReadBool reads a boolean from the reader.
func ReadBool[T ~bool](r *Reader, v *T) error {
	switch {
	case len(r.B) < SizeBool:
		return ErrUnexpectedEOF
	case r.B[0] > trueByte:
		return ErrInvalidBool
	default:
		newB := r.B[SizeBool:]
		*v = r.B[0] == trueByte
		r.B = newB
		return nil
	}
}

// ReadBools reads a length-prefixed packed repeated boolean field from the
// reader.
func ReadBools[S ~[]E, E ~bool](r *Reader, v *S) error {
	var length uint64
	if err := ReadUint(r, &length); err != nil {
		return err
	}
	if length > uint64(len(r.B)) {
		return ErrUnexpectedEOF
	}

	b := r.B[:length]
	r.B = r.B[length:]
	if err := UseMemory(r, length); err != nil {
		return err
	}
	// Making vs with len(b) proves to the compiler that b[i] can not exceed
	// either slice, removing all bounds checks from the loop.
	vs := make(S, len(b))
	for i := range vs {
		// This branch is typically predicted correctly for valid input, which
		// is faster than accumulating the bytes.
		if b[i] > trueByte {
			return ErrInvalidBool
		}
		vs[i] = b[i] == trueByte
	}
	*v = vs
	return nil
}

// ReadBoolsInto reads a length-prefixed packed repeated boolean field from the
// reader into vs. The field must contain exactly len(vs) values.
func ReadBoolsInto[S ~[]E, E ~bool](r *Reader, vs S) error {
	var length uint64
	if err := ReadUint(r, &length); err != nil {
		return err
	}
	if length > uint64(len(r.B)) {
		return ErrUnexpectedEOF
	}
	if length != uint64(len(vs)) {
		return ErrInvalidLength
	}

	// Slicing b by len(vs) proves to the compiler that b[i] can not exceed
	// either slice, removing all bounds checks from the loop.
	b := r.B[:len(vs)]
	r.B = r.B[length:]
	for i := range vs {
		// This branch is typically predicted correctly for valid input, which
		// is faster than accumulating the bytes.
		if b[i] > trueByte {
			return ErrInvalidBool
		}
		vs[i] = b[i] == trueByte
	}
	return nil
}

// AppendBool writes a boolean to the writer.
func AppendBool[T ~bool](w *Writer, b T) {
	v := falseByte
	if b {
		v = trueByte
	}
	w.B = append(w.B, v)
}

// AppendBools writes a length-prefixed packed repeated boolean field to the
// writer.
func AppendBools[S ~[]E, E ~bool](w *Writer, vs S) {
	b := w.B
	b = binary.AppendUvarint(b, uint64(len(vs))*SizeBool)
	for _, v := range vs {
		t := falseByte
		if v {
			t = trueByte
		}
		b = append(b, t)
	}
	w.B = b
}

// SizeBytes calculates the size the length-prefixed bytes would take if
// written.
func SizeBytes[T Bytes](v T) uint64 {
	length := uint64(len(v))
	return SizeUint(length) + length
}

// CountBytes counts the consecutive number of length-prefixed fields with the
// given tag. If a field is malformed, the number of fields before it is
// returned along with the error.
func CountBytes[T Bytes](bytes []byte, tag T) (uint64, error) {
	var (
		r     = Reader{B: bytes}
		count uint64
	)
	for HasPrefix(r.B, tag) {
		r.B = r.B[len(tag):]
		var length uint64
		if err := ReadUint(&r, &length); err != nil {
			return count, err
		}
		if length > uint64(len(r.B)) {
			return count, ErrUnexpectedEOF
		}
		r.B = r.B[length:]
		count++
	}
	return count, nil
}

// HasPrefix returns true if the bytes start with the given prefix.
func HasPrefix[T Bytes](bytes []byte, prefix T) bool {
	return len(bytes) >= len(prefix) && string(bytes[:len(prefix)]) == string(prefix)
}

// ReadString reads a string from the reader. The string is verified to be valid
// UTF-8.
func ReadString[T ~string](r *Reader, v *T) error {
	var length uint64
	if err := ReadUint(r, &length); err != nil {
		return err
	}
	if length > uint64(len(r.B)) {
		return ErrUnexpectedEOF
	}

	bytes := r.B[:length]
	newB := r.B[length:]
	if !utf8.Valid(bytes) {
		return ErrStringNotUTF8
	}
	r.B = newB

	if r.Unsafe {
		*v = T(unsafeString(bytes))
		return nil
	}
	if err := UseMemory(r, length); err != nil {
		return err
	}
	*v = T(bytes)
	return nil
}

// ValidString returns true if it is valid to encode the provided string. A
// string is valid to encode if it is valid UTF-8.
func ValidString[T ~string](v T) bool {
	return utf8.ValidString(string(v))
}

// ReadBytes reads a byte slice from the reader.
func ReadBytes[T ~[]byte](r *Reader, v *T) error {
	var length uint64
	if err := ReadUint(r, &length); err != nil {
		return err
	}
	if length > uint64(len(r.B)) {
		return ErrUnexpectedEOF
	}

	bytes := r.B[:length]
	r.B = r.B[length:]
	if !r.Unsafe {
		if err := UseMemory(r, length); err != nil {
			return err
		}
		bytes = slices.Clone(bytes)
	}
	*v = T(bytes)
	return nil
}

// SkipBytes advances the reader past a byte slice without reading it.
func SkipBytes(r *Reader) error {
	var length uint64
	if err := ReadUint(r, &length); err != nil {
		return err
	}
	if length > uint64(len(r.B)) {
		return ErrUnexpectedEOF
	}

	r.B = r.B[length:]
	return nil
}

// ReadSubReader reads a length-prefixed byte slice from r and sets sub to a
// Reader over those bytes. The bytes are never copied, regardless of r.Unsafe.
//
// All configuration of sub is inherited from r, except that sub.DepthLimit is
// one less than r.DepthLimit. If r.DepthLimit is 0, [ErrDepthLimitExceeded] is
// returned.
func ReadSubReader(r *Reader, sub *Reader) error {
	if r.DepthLimit == 0 {
		return ErrDepthLimitExceeded
	}
	var length uint64
	if err := ReadUint(r, &length); err != nil {
		return err
	}
	// Copying length and r.B into locals keeps the bounds check below valid for
	// the slicing. Otherwise both are reloaded after the stores, because length
	// is address-taken and sub may alias r.
	n := length
	b := r.B
	if n > uint64(len(b)) {
		return ErrUnexpectedEOF
	}

	sub.B = b[:n]
	sub.Unsafe = r.Unsafe
	sub.MemoryRemaining = r.MemoryRemaining
	sub.DepthLimit = r.DepthLimit - 1
	sub.Context = r.Context
	r.B = b[n:]
	return nil
}

// AppendBytes writes a length-prefixed byte slice to the writer.
func AppendBytes[T Bytes](w *Writer, v T) {
	b := w.B
	b = binary.AppendUvarint(b, uint64(len(v)))
	b = append(b, v...)
	w.B = b
}

// MakePointer sets *p to a new pointer after charging its size against the
// remaining memory of r. Other than charging memory, it is equivalent to
// `*p = new(T)`.
//
// This function is useful to use in auto-generated code, when the type of a
// variable is unknown.
func MakePointer[T any](r *Reader, p **T) error {
	var zero T
	if err := UseMemory(r, uint64(unsafe.Sizeof(zero))); err != nil {
		return err
	}
	*p = new(T)
	return nil
}

// MakeSlice sets *s to a new slice with the given length after charging its
// size against the remaining memory of r. Other than charging memory, it is
// equivalent to `*s = make(S, length)`.
//
// This function is useful to use in auto-generated code, when the type of a
// variable is unknown.
func MakeSlice[S ~[]E, E any](r *Reader, s *S, length uint64) error {
	if err := UseSliceMemory[E](r, length); err != nil {
		return err
	}
	*s = make(S, length)
	return nil
}

// MakeEntry returns the zero value of an element in the provided slice.
//
// This function is useful to use in auto-generated code, when the type of a
// variable is unknown. For example, if we have a variable `v` which we know to
// be a slice, but we do not know the type of the elements, we can use this
// function to leverage golang's type inference to create an element.
func MakeEntry[S ~[]E, E any](S) (_ E) {
	return
}

// MakeEntryNilPointer returns a nil pointer to an element in the provided
// slice.
//
// This function is useful to use in auto-generated code, when the type of a
// variable is unknown. For example, if we have a variable `v` which we know to
// be a slice, but we do not know the type of the elements, we can use this
// function to leverage golang's type inference to create the pointer.
func MakeEntryNilPointer[S ~[]E, E any](S) (_ *E) {
	return
}

// IsZero returns true if the value is the zero value for its type.
func IsZero[T comparable](v T) bool {
	var zero T
	return v == zero
}

// unsafeString converts a []byte to an unsafe string.
//
// Invariant: The input []byte must not be modified.
func unsafeString(b []byte) string {
	// avoid copying during the conversion
	return unsafe.String(unsafe.SliceData(b), len(b))
}

// NewCodec returns a [Codec] for messages described by s.
func NewCodec(s *Spec) (*Codec, error) {
	if !s.ValidCanoto() {
		return nil, ErrInvalidSpec
	}
	if err := s.validate(0); err != nil {
		return nil, err
	}
	var ancestors []*spec
	return &Codec{
		spec: newSpec(s, &ancestors),
	}, nil
}

// newSpec prepares s for use by the [Codec].
//
// ancestors is the stack of prepared messages enclosing s, which Recursive
// fields refer to. It is shared across the recursion so that preparing s is
// linear in its size.
//
// s must already be validated.
func newSpec(s *Spec, ancestors *[]*spec) *spec {
	var (
		m = &spec{
			fieldsByNumber: make(map[uint32]*field, len(s.Fields)),
			fieldsByName:   make(map[string]*field, len(s.Fields)),
		}
		oneOfs = make(map[string]uint32)
	)
	*ancestors = append(*ancestors, m)
	defer func() {
		*ancestors = (*ancestors)[:len(*ancestors)-1]
	}()

	for i := range s.Fields {
		ft := &s.Fields[i]
		f := &field{
			number:      ft.FieldNumber,
			name:        ft.Name,
			fixedLength: ft.FixedLength,
			repeated:    ft.Repeated,
			pointer:     ft.Pointer,
			kind:        ft.WhichCanotoType(),
			wireType:    Len,
		}

		if ft.OneOf != "" {
			id, ok := oneOfs[ft.OneOf]
			if !ok {
				id = uint32(len(oneOfs)) + 1 //#nosec G115 // Bounded by the number of fields
				oneOfs[ft.OneOf] = id
			}
			f.oneOf = id
		}

		switch f.kind {
		case FieldTypeInt:
			f.size = ft.TypeInt
		case FieldTypeUint:
			f.size = ft.TypeUint
		case FieldTypeFixedInt:
			f.size = ft.TypeFixedInt
		case FieldTypeFixedUint:
			f.size = ft.TypeFixedUint
		case FieldTypeFixedBytes:
			f.fixedBytes = ft.TypeFixedBytes
		case FieldTypeRecursive:
			a := *ancestors
			f.message = a[uint64(len(a))-ft.TypeRecursive]
		case FieldTypeMessage:
			f.message = newSpec(ft.TypeMessage, ancestors)
		}
		if !f.repeated {
			switch f.kind {
			case FieldTypeInt, FieldTypeUint, FieldTypeBool:
				f.wireType = Varint
			case FieldTypeFixedInt, FieldTypeFixedUint:
				f.wireType, _ = f.size.fixedWireType() // validated
			}
		}
		f.tag = Tag(f.number, f.wireType)
		m.fieldsByNumber[f.number] = f
		m.fieldsByName[f.name] = f
	}
	return m
}

// validate returns an error if s does not describe a message that could have
// been described by generated code. depth is the number of messages enclosing
// s.
//
// It is assumed that CacheCanoto has been called since the last modification
// to s.
func (s *Spec) validate(depth uint64) error {
	if len(s.Name) == 0 {
		return ErrInvalidSpec
	}

	depth++
	var (
		prevFieldNumber uint32
		names           = make(map[string]struct{}, len(s.Fields))
	)
	for i := range s.Fields {
		f := &s.Fields[i]
		if err := f.validate(depth); err != nil {
			return err
		}

		if f.FieldNumber <= prevFieldNumber {
			return ErrInvalidSpec
		}
		prevFieldNumber = f.FieldNumber

		if _, ok := names[f.Name]; ok {
			return ErrInvalidSpec
		}
		names[f.Name] = struct{}{}
	}
	return nil
}

// validate returns an error if f does not describe a field that could have
// been described by generated code. depth is the number of messages enclosing
// f.
//
// It is assumed that CacheCanoto has been called since the last modification
// to f.
func (f *FieldType) validate(depth uint64) error {
	switch {
	case false,
		f.FieldNumber == 0,
		f.FieldNumber > MaxFieldNumber,
		len(f.Name) == 0,
		f.FixedLength != 0 && !f.Repeated,
		len(f.OneOf) != 0 && f.Repeated:
		return ErrInvalidSpec
	}

	var (
		validSize     = true
		allowsPointer bool
	)
	switch f.WhichCanotoType() {
	case FieldTypeInt:
		_, _, validSize = f.TypeInt.shift()
	case FieldTypeUint:
		_, _, validSize = f.TypeUint.shift()
	case FieldTypeFixedInt:
		_, validSize = f.TypeFixedInt.fixedWireType()
	case FieldTypeFixedUint:
		_, validSize = f.TypeFixedUint.fixedWireType()
	case FieldTypeBool, FieldTypeString, FieldTypeFixedBytes:
	case FieldTypeBytes:
		allowsPointer = true
	case FieldTypeRecursive:
		if f.TypeRecursive > depth {
			return ErrInvalidRecursiveDepth
		}
		allowsPointer = true
	case FieldTypeMessage:
		if err := f.TypeMessage.validate(depth); err != nil {
			return err
		}
		allowsPointer = true
	default:
		return ErrUnknownFieldType
	}

	switch {
	case !validSize:
		return ErrUnexpectedFieldSize
	case f.Pointer && !allowsPointer:
		return ErrInvalidSpec
	default:
		return nil
	}
}

// Unmarshal parses r.B as the message described by the Codec's [Spec].
//
// Unmarshaling is limited by the options of r, which should be bounded when
// either the Spec or r.B is untrusted.
//
// This function is slower than calling [Field.UnmarshalCanotoFrom] on the type
// directly. This function should only be used when the concrete type can not be
// known ahead of time.
func (c *Codec) Unmarshal(r Reader) (Any, error) {
	return c.spec.unmarshal(&r)
}

// Marshal marshals a into bytes based on the Codec's [Spec].
//
// This function is significantly slower than calling MarshalCanoto on the type
// directly. This function should only be used when the concrete type can not be
// known ahead of time.
func (c *Codec) Marshal(a Any) ([]byte, error) {
	if err := c.spec.calculateSize(&a); err != nil {
		return nil, err
	}
	w := Writer{
		B: make([]byte, 0, a.cachedSize),
	}
	w, err := c.spec.marshal(w, &a)
	if err != nil {
		return nil, err
	}
	return w.B, nil
}

var _ json.Marshaler = Any{}

// MarshalJSON implements the [json.Marshaler] interface.
func (a Any) MarshalJSON() ([]byte, error) {
	var sb strings.Builder
	sb.WriteString("{")
	for i, f := range a.Fields {
		if i > 0 {
			sb.WriteString(",")
		}
		name, err := json.Marshal(f.Name)
		if err != nil {
			return nil, err
		}
		sb.Write(name)
		sb.WriteString(":")
		b, err := json.Marshal(f.Value)
		if err != nil {
			return nil, err
		}
		sb.Write(b)
	}
	sb.WriteString("}")
	return []byte(sb.String()), nil
}

// FieldTypeFromFint creates a [FieldType] specification for a fixed-size
// integer field. This is primarily used by generated code to build [Spec]
// values.
func FieldTypeFromFint[T integer](
	field T,
	fieldNumber uint32,
	name string,
	fixedLength uint64,
	repeated bool,
	oneOf string,
) FieldType {
	var (
		typeFixedInt  SizeEnum
		typeFixedUint SizeEnum
	)
	if isSigned[T]() {
		typeFixedInt = SizeOf(field)
	} else {
		typeFixedUint = SizeOf(field)
	}
	return FieldType{
		FieldNumber:   fieldNumber,
		Name:          name,
		FixedLength:   fixedLength,
		Repeated:      repeated,
		OneOf:         oneOf,
		TypeFixedInt:  typeFixedInt,
		TypeFixedUint: typeFixedUint,
	}
}

// FieldTypeFromField creates a [FieldType] specification for a message or
// custom [Field] type. This is primarily used by generated code to build [Spec]
// values.
//
// The first argument is only used for type inference.
func FieldTypeFromField[T any, PT FieldPointer[T]](
	_ PT,
	fieldNumber uint32,
	name string,
	fixedLength uint64,
	repeated bool,
	oneOf string,
	pointer bool,
	types []reflect.Type,
) FieldType {
	var (
		fieldType = reflect.TypeFor[T]()

		typeBytes     bool
		typeRecursive uint64
		typeMessage   *Spec
	)
	if index := slices.Index(types, fieldType); index >= 0 {
		typeRecursive = uint64(len(types) - index) //#nosec G115 // False positive
	} else {
		// Calling DescribeCanoto on a non-nil value supports implementations
		// with value receivers.
		typeMessage = PT(new(T)).DescribeCanoto(types...)
		// If this does not have a valid spec, it is treated as bytes.
		if typeMessage == nil {
			typeBytes = true
		}
	}
	return FieldType{
		FieldNumber:   fieldNumber,
		Name:          name,
		FixedLength:   fixedLength,
		Repeated:      repeated,
		OneOf:         oneOf,
		Pointer:       pointer,
		TypeBytes:     typeBytes,
		TypeRecursive: typeRecursive,
		TypeMessage:   typeMessage,
	}
}

// isSigned returns true if the integer type is signed.
func isSigned[T integer]() bool {
	return ^T(0) < T(0)
}

// SizeOf returns the size of the integer type.
func SizeOf[T integer](v T) SizeEnum {
	// The sizes of these integer types are defined by the Go specification,
	// so the result does not depend on the platform.
	switch unsafe.Sizeof(v) {
	case 1:
		return SizeEnum8
	case 2:
		return SizeEnum16
	case 4:
		return SizeEnum32
	default:
		return SizeEnum64
	}
}

func (s *spec) unmarshal(r *Reader) (Any, error) {
	var (
		minField uint32
		a        = Any{
			Fields: make([]AnyField, 0, countFields(r.B)),
		}
		oneOfs = make(map[uint32]struct{})
	)
	for HasNext(r) {
		fieldNumber, wireType, err := ReadTag(r)
		if err != nil {
			return Any{}, err
		}
		if fieldNumber < minField {
			return Any{}, ErrInvalidFieldOrder
		}

		f, ok := s.fieldsByNumber[fieldNumber]
		if !ok {
			return Any{}, ErrUnknownField
		}
		if wireType != f.wireType {
			return Any{}, ErrUnexpectedWireType
		}

		if f.oneOf != 0 {
			if _, ok := oneOfs[f.oneOf]; ok {
				return Any{}, ErrDuplicateOneOf
			}
			oneOfs[f.oneOf] = struct{}{}
		}

		value, err := f.unmarshal(r)
		if err != nil {
			return Any{}, err
		}
		a.Fields = append(a.Fields, AnyField{
			Name:  f.name,
			Value: value,
		})

		minField = fieldNumber + 1
	}
	return a, nil
}

// countFields counts the fields in a message, treating the entries of a
// repeated field as one field. Counting stops at the first malformed field.
func countFields(b []byte) int {
	var (
		r     = Reader{B: b}
		count int
		// Initially set to an invalid field number so that deduplication
		// doesn't need to handle 0s as a special case.
		prevFieldNumber uint32 = MaxFieldNumber + 1

		// Throw away values.
		v64 uint64
		v32 uint32
	)
	for HasNext(&r) {
		fieldNumber, wireType, err := ReadTag(&r)
		if err != nil {
			return count
		}
		switch wireType {
		case Varint:
			err = ReadUint(&r, &v64)
		case I64:
			err = ReadFint64(&r, &v64)
		case Len:
			err = SkipBytes(&r)
		case I32:
			err = ReadFint32(&r, &v32)
		}
		if err != nil {
			return count
		}
		// Repeated fields count as a single field.
		if fieldNumber != prevFieldNumber {
			count++
		}
		prevFieldNumber = fieldNumber
	}
	return count
}

func (s *spec) calculateSize(a *Any) error {
	var (
		size     uint64
		minField uint32
		oneOfs   = make(map[uint32]struct{})
	)
	for i := range a.Fields {
		af := &a.Fields[i]
		f, ok := s.fieldsByName[af.Name]
		if !ok {
			return ErrUnknownField
		}
		if f.number < minField {
			return ErrInvalidFieldOrder
		}

		if f.oneOf != 0 {
			if _, ok := oneOfs[f.oneOf]; ok {
				return ErrDuplicateOneOf
			}
			oneOfs[f.oneOf] = struct{}{}
		}

		contentSize, err := f.calculateSize(af)
		if err != nil {
			return err
		}

		size += uint64(len(f.tag)) + contentSize

		minField = f.number + 1
	}
	CacheUint64(&a.cachedSize, size)
	return nil
}

func (f *field) calculateSize(af *AnyField) (uint64, error) {
	var (
		size uint64
		err  error
	)
	switch f.kind {
	case FieldTypeInt:
		size, err = calculateSizePacked(f, af.Value, SizeInt[int64])
	case FieldTypeUint:
		size, err = calculateSizePacked(f, af.Value, SizeUint[uint64])
	case FieldTypeFixedInt:
		var elementSize uint64
		switch f.size {
		case SizeEnum32:
			elementSize = SizeFint32
		case SizeEnum64:
			elementSize = SizeFint64
		default:
			return 0, ErrUnexpectedFieldSize
		}
		size, err = calculateSizePacked(f, af.Value, func(int64) uint64 {
			return elementSize
		})
	case FieldTypeFixedUint:
		var elementSize uint64
		switch f.size {
		case SizeEnum32:
			elementSize = SizeFint32
		case SizeEnum64:
			elementSize = SizeFint64
		default:
			return 0, ErrUnexpectedFieldSize
		}
		size, err = calculateSizePacked(f, af.Value, func(uint64) uint64 {
			return elementSize
		})
	case FieldTypeBool:
		size, err = calculateSizePacked(f, af.Value, func(bool) uint64 {
			return SizeBool
		})
	case FieldTypeString:
		size, err = calculateSizeUnpacked(f, af.Value, func(v string) (uint64, bool, error) {
			if !utf8.ValidString(v) {
				return 0, false, ErrStringNotUTF8
			}
			return SizeBytes(v), len(v) == 0, nil
		})
	case FieldTypeBytes:
		if f.pointer && f.repeated {
			size, err = calculateSizeUnpacked(f, af.Value, func(v *[]byte) (uint64, bool, error) {
				if v == nil {
					return uint64(len(EmptyBytes)), true, nil
				}
				innerSize := SizeBytes(*v)
				outerLen := SizePointerPresenceTag + innerSize
				return SizeUint(outerLen) + outerLen, false, nil
			})
		} else {
			size, err = calculateSizeUnpacked(f, af.Value, func(v []byte) (uint64, bool, error) {
				// Non-nil pointers are not considered empty.
				return SizeBytes(v), len(v) == 0 && !f.pointer, nil
			})
		}
	case FieldTypeFixedBytes:
		size, err = calculateSizeUnpacked(f, af.Value, func(v []byte) (uint64, bool, error) {
			if uint64(len(v)) != f.fixedBytes {
				return 0, false, ErrInvalidLength
			}
			return SizeBytes(v), isBytesEmpty(v), nil
		})
	case FieldTypeRecursive, FieldTypeMessage:
		size, err = f.calculateSizeMessage(af)
	default:
		return 0, ErrUnknownFieldType
	}
	return size, err
}

func calculateSizePacked[T comparable](
	f *field,
	value any,
	size func(T) uint64,
) (uint64, error) {
	if !f.repeated {
		v, ok := value.(T)
		if !ok {
			return 0, ErrInvalidFieldType
		}
		if IsZero(v) {
			return 0, ErrZeroValue
		}
		return size(v), nil
	}

	vl, ok := value.([]T)
	if !ok {
		return 0, ErrInvalidFieldType
	}
	if f.fixedLength != 0 && uint64(len(vl)) != f.fixedLength {
		return 0, ErrInvalidLength
	}

	var (
		packedSize uint64
		isZero     = true
	)
	for _, v := range vl {
		packedSize += size(v)
		isZero = isZero && IsZero(v)
	}
	if len(vl) == 0 || (f.fixedLength > 0 && isZero) {
		return 0, ErrZeroValue
	}
	return SizeUint(packedSize) + packedSize, nil
}

// calculateSizeUnpacked calculates the size of a length-delimited field. Each
// entry is sized with size, which also reports whether the entry is zero.
func calculateSizeUnpacked[T any](
	f *field,
	value any,
	size func(T) (uint64, bool, error),
) (uint64, error) {
	if !f.repeated {
		v, ok := value.(T)
		if !ok {
			return 0, ErrInvalidFieldType
		}
		s, isZero, err := size(v)
		if err != nil {
			return 0, err
		}
		if isZero {
			return 0, ErrZeroValue
		}
		return s, nil
	}

	vl, ok := value.([]T)
	if !ok {
		return 0, ErrInvalidFieldType
	}
	if len(vl) == 0 || (f.fixedLength != 0 && uint64(len(vl)) != f.fixedLength) {
		return 0, ErrInvalidLength
	}

	var (
		// The tag of the first entry is not included in the field size.
		total  = uint64(len(f.tag)) * (uint64(len(vl)) - 1)
		isZero = true
	)
	for _, v := range vl {
		s, isEntryZero, err := size(v)
		if err != nil {
			return 0, err
		}
		total += s
		isZero = isZero && isEntryZero
	}
	if f.fixedLength > 0 && isZero {
		return 0, ErrZeroValue
	}
	return total, nil
}

func (f *field) calculateSizeMessage(af *AnyField) (uint64, error) {
	if !f.repeated {
		v, ok := af.Value.(Any)
		if !ok {
			return 0, ErrInvalidFieldType
		}
		// Non-nil pointers are not considered empty.
		if len(v.Fields) == 0 && !f.pointer {
			return 0, ErrZeroValue
		}
		if err := f.message.calculateSize(&v); err != nil {
			return 0, err
		}
		CacheUint64(&af.cachedSize, v.cachedSize)
		return SizeUint(v.cachedSize) + v.cachedSize, nil
	}

	if f.pointer {
		vl, ok := af.Value.([]*Any)
		if !ok {
			return 0, ErrInvalidFieldType
		}
		if len(vl) == 0 || (f.fixedLength != 0 && uint64(len(vl)) != f.fixedLength) {
			return 0, ErrInvalidLength
		}

		var (
			// The tag of the first entry is not included in the field size.
			total  = uint64(len(f.tag)) * (uint64(len(vl)) - 1)
			isZero = true
		)
		for _, v := range vl {
			if v == nil {
				total += uint64(len(EmptyBytes))
				continue
			}
			if err := f.message.calculateSize(v); err != nil {
				return 0, err
			}
			innerSize := atomic.LoadUint64(&v.cachedSize)
			outerLen := SizePointerPresenceTag + SizeUint(innerSize) + innerSize
			total += SizeUint(outerLen) + outerLen
			isZero = false
		}
		if f.fixedLength > 0 && isZero {
			return 0, ErrZeroValue
		}
		return total, nil
	}

	vl, ok := af.Value.([]Any)
	if !ok {
		return 0, ErrInvalidFieldType
	}
	if len(vl) == 0 || (f.fixedLength != 0 && uint64(len(vl)) != f.fixedLength) {
		return 0, ErrInvalidLength
	}

	var (
		// The tag of the first entry is not included in the field size.
		total  = uint64(len(f.tag)) * (uint64(len(vl)) - 1)
		isZero = true
	)
	for i := range vl {
		v := &vl[i]
		if err := f.message.calculateSize(v); err != nil {
			return 0, err
		}
		elementSize := atomic.LoadUint64(&v.cachedSize)
		total += SizeUint(elementSize) + elementSize
		isZero = isZero && len(v.Fields) == 0
	}
	if f.fixedLength > 0 && isZero {
		return 0, ErrZeroValue
	}
	return total, nil
}

func (s *spec) marshal(w Writer, a *Any) (Writer, error) {
	var minField uint32
	for i := range a.Fields {
		af := &a.Fields[i]
		f, ok := s.fieldsByName[af.Name]
		if !ok {
			return Writer{}, ErrUnknownField
		}
		if f.number < minField {
			return Writer{}, ErrInvalidFieldOrder
		}

		Append(&w, f.tag)

		var err error
		w, err = f.marshal(w, af)
		if err != nil {
			return Writer{}, err
		}

		minField = f.number + 1
	}
	return w, nil
}

func (f *field) unmarshal(r *Reader) (any, error) {
	switch f.kind {
	case FieldTypeInt:
		return f.unmarshalInt(r)
	case FieldTypeUint:
		return f.unmarshalUint(r)
	case FieldTypeFixedInt:
		return f.unmarshalFixedInt(r)
	case FieldTypeFixedUint:
		return f.unmarshalFixedUint(r)
	case FieldTypeBool:
		return f.unmarshalBool(r)
	case FieldTypeString:
		return f.unmarshalString(r)
	case FieldTypeBytes:
		return f.unmarshalBytes(r)
	case FieldTypeFixedBytes:
		return f.unmarshalFixedBytes(r)
	case FieldTypeRecursive, FieldTypeMessage:
		return f.unmarshalMessage(r)
	default:
		return nil, ErrUnknownFieldType
	}
}

func (f *field) marshal(w Writer, af *AnyField) (Writer, error) {
	switch f.kind {
	case FieldTypeInt:
		return f.marshalInt(w, af.Value)
	case FieldTypeUint:
		return f.marshalUint(w, af.Value)
	case FieldTypeFixedInt:
		return f.marshalFixedInt(w, af.Value)
	case FieldTypeFixedUint:
		return f.marshalFixedUint(w, af.Value)
	case FieldTypeBool:
		return f.marshalBool(w, af.Value)
	case FieldTypeString:
		return f.marshalString(w, af.Value)
	case FieldTypeBytes, FieldTypeFixedBytes:
		return f.marshalBytes(w, af.Value)
	case FieldTypeRecursive, FieldTypeMessage:
		return f.marshalMessage(w, af)
	default:
		return Writer{}, ErrUnknownFieldType
	}
}

func (f *field) unmarshalInt(r *Reader) (any, error) {
	var (
		read         func(*Reader) (int64, error)
		readRepeated func(*Reader, uint64) ([]int64, error)
	)
	switch f.size {
	case SizeEnum8:
		read, readRepeated = unmarshalInt[int8], unmarshalInts[int8]
	case SizeEnum16:
		read, readRepeated = unmarshalInt[int16], unmarshalInts[int16]
	case SizeEnum32:
		read, readRepeated = unmarshalInt[int32], unmarshalInts[int32]
	case SizeEnum64:
		read, readRepeated = unmarshalInt[int64], unmarshalInts[int64]
	default:
		return 0, ErrUnexpectedFieldSize
	}
	return unmarshalPackedVarint(
		f,
		r,
		read,
		readRepeated,
	)
}

func (f *field) marshalInt(w Writer, value any) (Writer, error) {
	var (
		minimum int64
		maximum int64
	)
	switch f.size {
	case SizeEnum8:
		minimum, maximum = math.MinInt8, math.MaxInt8
	case SizeEnum16:
		minimum, maximum = math.MinInt16, math.MaxInt16
	case SizeEnum32:
		minimum, maximum = math.MinInt32, math.MaxInt32
	case SizeEnum64:
		minimum, maximum = math.MinInt64, math.MaxInt64
	default:
		return Writer{}, ErrUnexpectedFieldSize
	}
	return marshalPacked(
		f,
		w,
		value,
		SizeInt[int64],
		func(w Writer, value int64) (Writer, error) {
			if value < minimum || value > maximum {
				return Writer{}, ErrOverflow
			}
			AppendInt(&w, value)
			return w, nil
		},
	)
}

func (f *field) unmarshalUint(r *Reader) (any, error) {
	var (
		read         func(*Reader) (uint64, error)
		readRepeated func(*Reader, uint64) ([]uint64, error)
	)
	switch f.size {
	case SizeEnum8:
		read, readRepeated = unmarshalUint[uint8], unmarshalUints[uint8]
	case SizeEnum16:
		read, readRepeated = unmarshalUint[uint16], unmarshalUints[uint16]
	case SizeEnum32:
		read, readRepeated = unmarshalUint[uint32], unmarshalUints[uint32]
	case SizeEnum64:
		read, readRepeated = unmarshalUint[uint64], unmarshalUints[uint64]
	default:
		return 0, ErrUnexpectedFieldSize
	}
	return unmarshalPackedVarint(
		f,
		r,
		read,
		readRepeated,
	)
}

func (f *field) marshalUint(w Writer, value any) (Writer, error) {
	var maximum uint64
	switch f.size {
	case SizeEnum8:
		maximum = math.MaxUint8
	case SizeEnum16:
		maximum = math.MaxUint16
	case SizeEnum32:
		maximum = math.MaxUint32
	case SizeEnum64:
		maximum = math.MaxUint64
	default:
		return Writer{}, ErrUnexpectedFieldSize
	}
	return marshalPacked(
		f,
		w,
		value,
		SizeUint[uint64],
		func(w Writer, value uint64) (Writer, error) {
			if value > maximum {
				return Writer{}, ErrOverflow
			}
			AppendUint(&w, value)
			return w, nil
		},
	)
}

func (f *field) unmarshalFixedInt(r *Reader) (any, error) {
	var read func(*Reader) (int64, error)
	switch f.size {
	case SizeEnum32:
		read = func(r *Reader) (int64, error) {
			var v int32
			err := ReadFint32(r, &v)
			return int64(v), err
		}
	case SizeEnum64:
		read = func(r *Reader) (int64, error) {
			var v int64
			err := ReadFint64(r, &v)
			return v, err
		}
	default:
		return 0, ErrUnexpectedFieldSize
	}
	return unmarshalPackedFixed(
		f,
		r,
		read,
		f.size,
	)
}

func (f *field) marshalFixedInt(w Writer, value any) (Writer, error) {
	var (
		elementSize uint64
		write       func(w Writer, value int64) (Writer, error)
	)
	switch f.size {
	case SizeEnum32:
		elementSize = SizeFint32
		write = func(w Writer, value int64) (Writer, error) {
			if value < math.MinInt32 || value > math.MaxInt32 {
				return Writer{}, ErrOverflow
			}
			AppendFint32(&w, int32(value))
			return w, nil
		}
	case SizeEnum64:
		elementSize = SizeFint64
		write = func(w Writer, value int64) (Writer, error) {
			AppendFint64(&w, value)
			return w, nil
		}
	default:
		return Writer{}, ErrUnexpectedFieldSize
	}
	return marshalPacked(
		f,
		w,
		value,
		func(int64) uint64 { return elementSize },
		write,
	)
}

func (f *field) unmarshalFixedUint(r *Reader) (any, error) {
	var read func(*Reader) (uint64, error)
	switch f.size {
	case SizeEnum32:
		read = func(r *Reader) (uint64, error) {
			var v uint32
			err := ReadFint32(r, &v)
			return uint64(v), err
		}
	case SizeEnum64:
		read = func(r *Reader) (uint64, error) {
			var v uint64
			err := ReadFint64(r, &v)
			return v, err
		}
	default:
		return 0, ErrUnexpectedFieldSize
	}
	return unmarshalPackedFixed(
		f,
		r,
		read,
		f.size,
	)
}

func (f *field) marshalFixedUint(w Writer, value any) (Writer, error) {
	var (
		elementSize uint64
		write       func(w Writer, value uint64) (Writer, error)
	)
	switch f.size {
	case SizeEnum32:
		elementSize = SizeFint32
		write = func(w Writer, value uint64) (Writer, error) {
			if value > math.MaxUint32 {
				return Writer{}, ErrOverflow
			}
			AppendFint32(&w, uint32(value))
			return w, nil
		}
	case SizeEnum64:
		elementSize = SizeFint64
		write = func(w Writer, value uint64) (Writer, error) {
			AppendFint64(&w, value)
			return w, nil
		}
	default:
		return Writer{}, ErrUnexpectedFieldSize
	}
	return marshalPacked(
		f,
		w,
		value,
		func(uint64) uint64 { return elementSize },
		write,
	)
}

func (f *field) unmarshalBool(r *Reader) (any, error) {
	return unmarshalPackedFixed(
		f,
		r,
		func(r *Reader) (bool, error) {
			var v bool
			err := ReadBool(r, &v)
			return v, err
		},
		SizeEnum8,
	)
}

func (f *field) marshalBool(w Writer, value any) (Writer, error) {
	return marshalPacked(
		f,
		w,
		value,
		func(bool) uint64 { return SizeBool },
		func(w Writer, value bool) (Writer, error) {
			AppendBool(&w, value)
			return w, nil
		},
	)
}

func (f *field) unmarshalString(r *Reader) (any, error) {
	return unmarshalUnpacked(
		f,
		r,
		ReadBytes[[]byte],
		func(msgBytes []byte) (string, bool, error) {
			if !utf8.Valid(msgBytes) {
				return "", false, ErrStringNotUTF8
			}
			return string(msgBytes), len(msgBytes) == 0, nil
		},
	)
}

func (f *field) marshalString(w Writer, value any) (Writer, error) {
	return marshalUnpacked(
		f,
		w,
		value,
		func(w Writer, value string) (Writer, error) {
			AppendBytes(&w, value)
			return w, nil
		},
	)
}

func (f *field) unmarshalBytes(r *Reader) (any, error) {
	if f.pointer && f.repeated {
		return unmarshalUnpacked(f, r, ReadSubReader, func(msgReader Reader) (*[]byte, bool, error) {
			if !HasNext(&msgReader) {
				return nil, true, nil
			}
			if err := UnwrapPointer(&msgReader); err != nil {
				return nil, false, err
			}
			msgBytes := msgReader.B
			if !r.Unsafe {
				if err := UseMemory(r, uint64(len(msgBytes))); err != nil {
					return nil, false, err
				}
				msgBytes = slices.Clone(msgBytes)
			}
			return &msgBytes, false, nil
		})
	}
	return unmarshalUnpacked(
		f,
		r,
		ReadBytes[[]byte],
		func(msgBytes []byte) ([]byte, bool, error) {
			// Non-nil pointers are not considered empty.
			return msgBytes, len(msgBytes) == 0 && !f.pointer, nil
		},
	)
}

func (f *field) marshalBytes(w Writer, value any) (Writer, error) {
	if f.pointer && f.repeated {
		return marshalUnpacked(
			f,
			w,
			value,
			func(w Writer, value *[]byte) (Writer, error) {
				if value == nil {
					Append(&w, EmptyBytes)
					return w, nil
				}
				AppendUint(&w, SizePointerPresenceTag+SizeBytes(*value))
				Append(&w, PointerPresenceTag)
				AppendBytes(&w, *value)
				return w, nil
			},
		)
	}
	return marshalUnpacked(
		f,
		w,
		value,
		func(w Writer, value []byte) (Writer, error) {
			AppendBytes(&w, value)
			return w, nil
		},
	)
}

func (f *field) unmarshalFixedBytes(r *Reader) (any, error) {
	return unmarshalUnpacked(
		f,
		r,
		func(r *Reader, msgBytes *[]byte) error {
			var length uint64
			if err := ReadUint(r, &length); err != nil {
				return err
			}
			if length != f.fixedBytes {
				return ErrInvalidLength
			}
			if length > uint64(len(r.B)) {
				return ErrUnexpectedEOF
			}
			*msgBytes = r.B[:length]
			r.B = r.B[length:]
			return nil
		},
		func(msgBytes []byte) ([]byte, bool, error) {
			return slices.Clone(msgBytes), isBytesEmpty(msgBytes), nil
		},
	)
}

func (f *field) unmarshalMessage(r *Reader) (any, error) {
	// unmarshal reads a message from msgReader, charging its memory to r.
	unmarshal := func(msgReader Reader) (Any, error) {
		msgReader.MemoryRemaining = r.MemoryRemaining
		a, err := f.message.unmarshal(&msgReader)
		r.MemoryRemaining = msgReader.MemoryRemaining
		return a, err
	}
	if f.pointer && f.repeated {
		return unmarshalUnpacked(f, r, ReadSubReader, func(msgReader Reader) (*Any, bool, error) {
			if !HasNext(&msgReader) {
				return nil, true, nil
			}
			if err := UnwrapPointer(&msgReader); err != nil {
				return nil, false, err
			}
			a, err := unmarshal(msgReader)
			return &a, false, err
		})
	}
	return unmarshalUnpacked(f, r, ReadSubReader, func(msgReader Reader) (Any, bool, error) {
		if !HasNext(&msgReader) {
			return Any{}, !f.pointer, nil
		}
		a, err := unmarshal(msgReader)
		return a, false, err
	})
}

func (f *field) marshalMessage(w Writer, af *AnyField) (Writer, error) {
	if !f.repeated {
		v, ok := af.Value.(Any)
		if !ok {
			return Writer{}, ErrInvalidFieldType
		}
		AppendUint(&w, atomic.LoadUint64(&af.cachedSize))
		return f.message.marshal(w, &v)
	}

	if f.pointer {
		vl, ok := af.Value.([]*Any)
		if !ok {
			return Writer{}, ErrInvalidFieldType
		}
		if len(vl) == 0 {
			return Writer{}, ErrInvalidLength
		}

		marshalElement := func(w Writer, v *Any) (Writer, error) {
			if v == nil {
				Append(&w, EmptyBytes)
				return w, nil
			}
			innerSize := atomic.LoadUint64(&v.cachedSize)
			AppendUint(&w, SizePointerPresenceTag+SizeUint(innerSize)+innerSize)
			Append(&w, PointerPresenceTag)
			AppendUint(&w, innerSize)
			return f.message.marshal(w, v)
		}

		var err error
		w, err = marshalElement(w, vl[0])
		if err != nil {
			return Writer{}, err
		}

		for _, v := range vl[1:] {
			Append(&w, f.tag)
			w, err = marshalElement(w, v)
			if err != nil {
				return Writer{}, err
			}
		}
		return w, nil
	}

	vl, ok := af.Value.([]Any)
	if !ok {
		return Writer{}, ErrInvalidFieldType
	}
	if len(vl) == 0 {
		return Writer{}, ErrInvalidLength
	}

	marshalElement := func(w Writer, v *Any) (Writer, error) {
		innerSize := atomic.LoadUint64(&v.cachedSize)
		AppendUint(&w, innerSize)
		return f.message.marshal(w, v)
	}

	var err error
	w, err = marshalElement(w, &vl[0])
	if err != nil {
		return Writer{}, err
	}

	rvl := vl[1:]
	for i := range rvl {
		Append(&w, f.tag)
		w, err = marshalElement(w, &rvl[i])
		if err != nil {
			return Writer{}, err
		}
	}
	return w, nil
}

func unmarshalInt[T Int](r *Reader) (int64, error) {
	var v T
	err := ReadInt(r, &v)
	return int64(v), err
}

func unmarshalUint[T Uint](r *Reader) (uint64, error) {
	var v T
	err := ReadUint(r, &v)
	return uint64(v), err
}

// packedVarintsLength returns the length of the slice to read a packed varint
// field into, when the field must contain exactly fixedLength values.
func packedVarintsLength(r *Reader, fixedLength uint64) (uint64, error) {
	var (
		peek = Reader{B: r.B, Unsafe: true}
		b    []byte
	)
	if err := ReadBytes(&peek, &b); err != nil {
		return 0, err
	}
	// The spec may be malicious, so fixedLength is bounded by the actual number
	// of values in the field. If the field contains fewer than fixedLength
	// values, the returned length still exceeds the number of values so that
	// reading the field fails as if we allocated the full fixedLength.
	return min(fixedLength, CountInts(b)+1), nil
}

// unmarshalInts reads a packed repeated zigzag encoded varint field. If
// fixedLength is non-zero, the field must contain exactly fixedLength values.
func unmarshalInts[T Int](r *Reader, fixedLength uint64) ([]int64, error) {
	var (
		vs  []T
		err error
	)
	if fixedLength == 0 {
		_, err = ReadInts(r, &vs)
	} else {
		var length uint64
		length, err = packedVarintsLength(r, fixedLength)
		if err != nil {
			return nil, err
		}
		vs = make([]T, length)
		_, err = ReadIntsInto(r, vs)
	}
	if err != nil {
		return nil, err
	}

	values := make([]int64, len(vs))
	for i, v := range vs {
		values[i] = int64(v)
	}
	return values, nil
}

// unmarshalUints reads a packed repeated varint field. If fixedLength is
// non-zero, the field must contain exactly fixedLength values.
func unmarshalUints[T Uint](r *Reader, fixedLength uint64) ([]uint64, error) {
	var (
		vs  []T
		err error
	)
	if fixedLength == 0 {
		_, err = ReadUints(r, &vs)
	} else {
		var length uint64
		length, err = packedVarintsLength(r, fixedLength)
		if err != nil {
			return nil, err
		}
		vs = make([]T, length)
		_, err = ReadUintsInto(r, vs)
	}
	if err != nil {
		return nil, err
	}

	values := make([]uint64, len(vs))
	for i, v := range vs {
		values[i] = uint64(v)
	}
	return values, nil
}

// unmarshalPackedVarint reads a varint field. Repeated fields are read with
// the same functions as the generated code, so that both return the same
// errors.
func unmarshalPackedVarint[T comparable](
	f *field,
	r *Reader,
	unmarshal func(r *Reader) (T, error),
	unmarshalRepeated func(r *Reader, fixedLength uint64) ([]T, error),
) (any, error) {
	if !f.repeated {
		// If there is only one entry, read it.
		value, err := unmarshal(r)
		if err != nil {
			return nil, err
		}
		if IsZero(value) {
			return nil, ErrZeroValue
		}
		return value, nil
	}

	values, err := unmarshalRepeated(r, f.fixedLength)
	if err != nil {
		return nil, err
	}
	isZero := true
	for _, value := range values {
		isZero = isZero && IsZero(value)
	}
	if len(values) == 0 || (f.fixedLength > 0 && isZero) {
		return nil, ErrZeroValue
	}
	return values, nil
}

func marshalPacked[T comparable](
	f *field,
	w Writer,
	value any,
	size func(T) uint64,
	marshal func(w Writer, value T) (Writer, error),
) (Writer, error) {
	if !f.repeated {
		// If there is only one entry, write it.
		v, ok := value.(T)
		if !ok {
			return Writer{}, ErrInvalidFieldType
		}
		return marshal(w, v)
	}

	vl, ok := value.([]T)
	if !ok {
		return Writer{}, ErrInvalidFieldType
	}

	var packedSize uint64
	for _, v := range vl {
		packedSize += size(v)
	}
	AppendUint(&w, packedSize)

	var err error
	for _, v := range vl {
		w, err = marshal(w, v)
		if err != nil {
			return Writer{}, err
		}
	}
	return w, nil
}

func unmarshalPackedFixed[T comparable](
	f *field,
	r *Reader,
	unmarshal func(r *Reader) (T, error),
	sizeEnum SizeEnum,
) (any, error) {
	if !f.repeated {
		// If there is only one entry, read it.
		value, err := unmarshal(r)
		if err != nil {
			return nil, err
		}
		if IsZero(value) {
			return nil, ErrZeroValue
		}
		return value, nil
	}

	// Read the full packed bytes.
	var msgBytes []byte
	if err := ReadBytes(r, &msgBytes); err != nil {
		return nil, err
	}

	shift, mask, ok := sizeEnum.shift()
	if !ok {
		return nil, ErrUnexpectedFieldSize
	}
	numMsgBytes := uint64(len(msgBytes))
	count := numMsgBytes >> shift
	if numMsgBytes&mask != 0 || (f.fixedLength != 0 && count != f.fixedLength) {
		return nil, ErrInvalidLength
	}

	values := make([]T, count)
	remainingBytes := r.B
	r.B = msgBytes
	isZero := true
	for i := range values {
		value, err := unmarshal(r)
		if err != nil {
			return nil, err
		}
		values[i] = value
		isZero = isZero && IsZero(value)
	}
	if count == 0 || (f.fixedLength > 0 && isZero) {
		return nil, ErrZeroValue
	}
	r.B = remainingBytes
	return values, nil
}

// unmarshalUnpacked reads a length-delimited field. Each entry is read with
// read and then converted into a value with unmarshal.
func unmarshalUnpacked[E, T any](
	f *field,
	r *Reader,
	read func(r *Reader, entry *E) error,
	unmarshal func(entry E) (T, bool, error),
) (any, error) {
	// Read the first entry manually because the tag is already stripped.
	var entry E
	if err := read(r, &entry); err != nil {
		return nil, err
	}
	if !f.repeated {
		// If there is only one entry, return it.
		value, isZero, err := unmarshal(entry)
		if err != nil {
			return nil, err
		}
		if isZero {
			return nil, ErrZeroValue
		}
		return value, nil
	}

	// Count the number of additional entries after the first entry.
	var count, capacity uint64
	if f.fixedLength == 0 {
		countMinus1, err := CountBytes(r.B, f.tag)
		if err != nil {
			return nil, err
		}
		count = countMinus1 + 1
		capacity = count
	} else {
		// The spec is untrusted, so the fixed length is bounded by the number
		// of entries present before it is used to size the allocation. The
		// error is ignored because, if the malformed entry is part of this
		// field, reading the entries below reports it.
		countMinus1, _ := CountBytes(r.B, f.tag)
		count = f.fixedLength
		capacity = min(count, countMinus1+1)
	}

	value, isZero, err := unmarshal(entry)
	if err != nil {
		return nil, err
	}

	values := make([]T, 1, capacity)
	values[0] = value

	// Read the rest of the entries, stripping the tag each time.
	for range count - 1 {
		if !HasPrefix(r.B, f.tag) {
			return nil, ErrUnknownField
		}
		r.B = r.B[len(f.tag):]

		if err := read(r, &entry); err != nil {
			return nil, err
		}

		value, isFieldZero, err := unmarshal(entry)
		if err != nil {
			return nil, err
		}
		values = append(values, value)
		isZero = isZero && isFieldZero
	}
	if f.fixedLength > 0 && isZero {
		return nil, ErrZeroValue
	}
	return values, nil
}

func marshalUnpacked[T any](
	f *field,
	w Writer,
	value any,
	marshal func(w Writer, value T) (Writer, error),
) (Writer, error) {
	if !f.repeated {
		// If there is only one entry, write it.
		v, ok := value.(T)
		if !ok {
			return Writer{}, ErrInvalidFieldType
		}
		return marshal(w, v)
	}

	vl, ok := value.([]T)
	if !ok {
		return Writer{}, ErrInvalidFieldType
	}

	if len(vl) == 0 {
		return Writer{}, ErrInvalidLength
	}

	// Write the first entry manually because the tag is already written.
	var err error
	w, err = marshal(w, vl[0])
	if err != nil {
		return Writer{}, err
	}

	for _, v := range vl[1:] {
		Append(&w, f.tag)
		w, err = marshal(w, v)
		if err != nil {
			return Writer{}, err
		}
	}
	return w, nil
}

// isBytesEmpty returns true if the byte slice is all zeros.
func isBytesEmpty(b []byte) bool {
	for _, v := range b {
		if v != 0 {
			return false
		}
	}
	return true
}
